4class Board {
5    public:
6
7
8        // count variable
9        int count = 0;
10
11
12        char board[9] = { ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ' };
13
14        void print_board() {
15            cout << " " << board[0] << " | " << board[1] << " | " << board[2] << endl;
16            cout << "-----------" << endl;
17            cout << " " << board[3] << " | " << board[4] << " | " << board[5] << endl;
18            cout << "-----------" << endl;
19            cout << " " << board[6] << " | " << board[7] << " | " << board[8] << endl;
20        }
21
22        bool update_board(int position, char type) {
23
24            // if a player selects position n, n-1 index should be updated
25            // if the position is not already filled, update the board
26            if (board[position - 1] == ' ') {
27                board[position - 1] = type;
28
29
30                // increase the value of count by 1
31                ++count;
32
33                return true;
34            }
35
36            // if the position is already filled, ask user to select another position
37            else {
38                cout << "Position already selected. Select another position.";
39                return false;
40            }
41        }
42
43
44        // if all variables are selected and there is no winner, it's draw
45        // return true if it's draw
46        bool check_draw() {
47
48            // check if count == 9
49            if (count == 9) {
50                return true;
51            } 
52            else {
53                return false;
54            }
55        }
56
57        // return true if three symbols appears in a row
58        bool check_winner(char type) {
59            if ((board[0] == type && board[1] == type && board[2] == type)
60                    || (board[3] == type && board[4] == type && board[5] == type)
61                    || (board[6] == type && board[7] == type && board[8] == type)
62                    || (board[0] == type && board[3] == type && board[6] == type)
63                    || (board[1] == type && board[4] == type && board[7] == type)
64                    || (board[2] == type && board[5] == type && board[8] == type)
65                    || (board[0] == type && board[4] == type && board[8] == type)
66                    || (board[2] == type && board[4] == type && board[6] == type)) {
67                return true;
68            }
69
70            else {
71                return false;
72            }
73
74        }
75
76};
