78class Player {
79    public:
80
81        string name;
82        char type;
83
84        // function to select the player type and name
85        void set_info(char type) {
86
87            // player type is 'X' if parameter is 'X' or 'x'            
88            if (type == 'X' || type == 'x') {
89
90                // set member variable to 'X'
91                this->type = 'X';
92
93                // get player name
94                cout << "Player selecting " << this->type << ", enter your name: ";
95                getline(cin, name);
96            }
97
98            // player type is 'O' if parameter is any other character 
99            else {
100                this->type = 'O';
101                cout << "Player selecting " << this->type << ", enter your name: ";
102                getline(cin, name);
103            }
104        }
105};
