107class Game {   
108    public:
109
110        Board board;
111
112        Player player1;
113        Player player2;
114        Player* current_player;
115        
116        // constructor to set player data
117        Game() {
118            player1.set_info('X');
119            player2.set_info('O');
120            current_player = &player1;
121        }
122
123        void play() {
124            
125            int position;
126
127            // message to prompt player for their position
128            string message = "enter the position (1 - 9): ";
129
130            // using an infinite loop to run the game
131            // we will later add conditions to terminate the loop
132            while (true) {
133
134                cout << current_player->name << " " << message;
135                cin >> position;
136
137                // the update_board() function returns true if
138                // the user selected position is not already filled
139                bool update = board.update_board(position, current_player->type);
140
141                // update the board if the selected position is not filled
142                if (update) {
143
144                    board.print_board();
145
146                    // change current player when board is updated
147                    if (current_player == &player1) {
148                        current_player = &player2;
149                    }
150
151                    else {
152                        current_player = &player1;
153                    }
154                }
155            }
156        }
157};
